Structured Text<pre><code>PROGRAM _CYCLIC

    // Existing Alarm Config
    // NB! Create an AlarmX setup in configuration view with a .mpalarmxlist file that contains a 'demo1' alarm
    BrdkAlarmControl_[0].Enable := TRUE;
    BrdkAlarmControl_[0].MpLinkCore := ADR(mpAlarmXCore);
    BrdkAlarmControl_[0].MpLinkList := ADR(mpAlarmXList);
    BrdkAlarmControl_[0].Name := 'demo1';
    //BrdkAlarmControl_[0].Condition := alarmVar;
    //BrdkAlarmControl_[0].Inhibit := plcIsSimulated;
    //BrdkAlarmControl_[0].Delay := t#5s;
    BrdkAlarmControl_[0]();

    // New Alarm Config
    BrdkAlarmControl_[1].Enable := TRUE;
    BrdkAlarmControl_[1].MpLinkCore := ADR(mpAlarmXCore);
    BrdkAlarmControl_[1].MpLinkList := ADR(mpAlarmXList);
    BrdkAlarmControl_[1].AlarmConfig.Behavior.Type := mpALARMX_CFG_LIST_PERSISTENT;
    BrdkAlarmControl_[1].AlarmConfig.Name := 'demo2';
    BrdkAlarmControl_[1].AlarmConfig.Message := 'This is a demo alarm created at runtime';
    BrdkAlarmControl_[1].AlarmConfig.Code := 50;
    BrdkAlarmControl_[1].AlarmConfig.Severity := 1;
    //BrdkAlarmControl_[1].Condition := alarmVar;
    //BrdkAlarmControl_[1].Inhibit := plcIsSimulated;
    //BrdkAlarmControl_[1].Delay := t#5s;
    BrdkAlarmControl_[1]();

    // Existing alarm configuration for indexed module
    // Add multiple entries of the same list in .mpalarmxcore with different 'Argument1' (and optional 'Code offset')
    // Create a dynamic alarm in .mpalarmxlist: demo3_module{1} (message: Demo alarm with a module number {1})
    BrdkAlarmControl_[2].Enable := TRUE;
    BrdkAlarmControl_[2].MpLinkCore := ADR(mpAlarmXCore);
    BrdkAlarmControl_[2].MpLinkList := ADR(mpAlarmXList);
    BrdkAlarmControl_[2].NameInConfig := 'demo3_module{1}';
    BrdkAlarmControl_[2].Name := 'demo3_module1';
    BrdkAlarmControl_[2]();

    BrdkAlarmControl_[3].Enable := TRUE;
    BrdkAlarmControl_[3].MpLinkCore := ADR(mpAlarmXCore);
    BrdkAlarmControl_[3].MpLinkList := ADR(mpAlarmXList);
    BrdkAlarmControl_[3].NameInConfig := 'demo3_module{1}';
    BrdkAlarmControl_[3].Name := 'demo3_module2';
    BrdkAlarmControl_[3]();

    // NB!
    // New alarm configuration for indexed module needs setup of lists
    // This is not supported by BrdkAlarmControl and must be setup externally using MpAlarmXCfgCoreListsType


    // Check for alarm reaction
    FOR i := 0 TO SIZEOF(BrdkAlarmControl_) / SIZEOF(BrdkAlarmControl_[0]) -1 DO
        IF BrdkAlarmControl_[i].Active THEN
            CASE BrdkAlarmControl_[i].Info.Severity OF
                // Commands to e.g. BrdkPackML can be set here based on severity
                1: // ABORT

                2: // STOP

                3: // WARNING / INFO

            END_CASE
        END_IF
    END_FOR


    // Alarm Query for active alarms
    // NB! Create a Query in .mpalarmxquery named 'activeAlarms'
    // SELECT
    //   Name ::&lt;TaskName&gt;:activeAlarms.name[]
    //   Code ::&lt;TaskName&gt;:activeAlarms.code[]
    //   Message ::&lt;TaskName&gt;:activeAlarms.message[]
    // WHERE
    //   StateActive = TRUE
    activeAlarms.MpAlarmXQuery_0.MpLink := ADR(mpAlarmXQuery);
    activeAlarms.MpAlarmXQuery_0.Name := ADR('activeAlarms');
    activeAlarms.MpAlarmXQuery_0.Enable := TRUE;
    activeAlarms.MpAlarmXQuery_0.Execute := TRUE;
    activeAlarms.MpAlarmXQuery_0();
    IF activeAlarms.MpAlarmXQuery_0.CommandDone THEN
        activeAlarms.MpAlarmXQuery_0.Execute := FALSE;
        activeAlarms.MpAlarmXQuery_0();
    END_IF

    // Acknowledge first alarm in the list from the query
    IF activeAlarms.acknowledgeFirst THEN
        activeAlarms.acknowledgeFirst := FALSE;
        IF activeAlarms.name[0] &lt;&gt; '' THEN
            MpAlarmXAcknowledge(mpAlarmXCore, activeAlarms.name[0]);
        END_IF
    END_IF

END_PROGRAM
</code></pre>
